*/

with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLID))) as HUB_CLAIM_HK
        , REPUDIATION_REASON as REPUDIATION_REASON
        , REPUDIATION_DT as REPUDIATION_DATE
        , 'BJAZ_HM_HCM_EXTRACT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcm_extract') }}
    where (nullif(trim(CLID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , REPUDI_REMARK as REPUDIATION_REASON
        , REPUDI_DATE as REPUDIATION_DATE
        , 'BJAZ_HM_PRO_ASSESSMENT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_pro_assessment') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__BJAZ_CLAIM_ID))) as HUB_CLAIM_HK
        , REJECTION_REASON as REPUDIATION_REASON
        , cast(null as varchar) as REPUDIATION_DATE
        , 'BJAZ_TPA_CLAIM_DETAILS_WS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_tpa_claim_details_ws') }}
    where (nullif(trim(BJAZ_CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , REPUD_REMARKS as REPUDIATION_REASON
        , REPUD_DATE as REPUDIATION_DATE
        , 'BJAZ_HM_HCS_TECH_ASSESS_COV' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcs_tech_assess_cov') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then REPUDIATION_REASON end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then REPUDIATION_REASON end)) as REPUDIATION_REASON,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then REPUDIATION_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then REPUDIATION_DATE end)) as REPUDIATION_DATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when REPUDIATION_REASON is not null or REPUDIATION_DATE is not null
                     then md5(upper(coalesce(cast(REPUDIATION_REASON as varchar), '') || '|' || coalesce(cast(REPUDIATION_DATE as varchar), '')))
                end as SAT_CLAIM_REPUDIATION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_REPUDIATION_HASHDIFF is not null
